	router.GET(options.BaseURL+"/api-keys", wrapper.ListApiKeys)
	router.POST(options.BaseURL+"/api-keys", wrapper.CreateApiKey)
	router.DELETE(options.BaseURL+"/api-keys/:clientId", wrapper.RevokeApiKey)
